import heapq

def stable_toposort(graph):
    indegree = {}
    rev = {}
    for node, deps in graph.items():
        deps = list(deps)
        indegree[node] = len(deps)
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"missing dependency: {dep!r}")
            rev.setdefault(dep, []).append(node)

    nodes = list(graph)
    index = {node: i for i, node in enumerate(nodes)}
    ready = [index[node] for node in graph if indegree[node] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        idx = heapq.heappop(ready)
        node = nodes[idx]
        result.append(node)
        for dependent in rev.get(node, []):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, index[dependent])

    if len(result) != len(graph):
        raise ValueError("cycle detected")
    return result

