def schema_drift(expected, actual):
    drift = []

    def add_leaf_paths(obj, path):
        if not isinstance(obj, dict) or not obj:
            drift.append(path)
            return
        for key, value in obj.items():
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(value, dict):
                add_leaf_paths(value, child_path)
            else:
                drift.append(child_path)

    def compare(exp, act, path):
        exp_keys = set(exp.keys())
        act_keys = set(act.keys())

        for key in exp_keys - act_keys:
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(exp[key], dict):
                add_leaf_paths(exp[key], child_path)
            else:
                drift.append(child_path)

        for key in act_keys - exp_keys:
            child_path = f"{path}.{key}" if path else str(key)
            if isinstance(act[key], dict):
                add_leaf_paths(act[key], child_path)
            else:
                drift.append(child_path)

        for key in exp_keys & act_keys:
            child_path = f"{path}.{key}" if path else str(key)
            exp_val = exp[key]
            act_val = act[key]

            if isinstance(exp_val, dict) and isinstance(act_val, dict):
                compare(exp_val, act_val, child_path)
            elif isinstance(exp_val, dict) or isinstance(act_val, dict):
                drift.append(child_path)
            elif exp_val != act_val:
                drift.append(child_path)

    compare(expected, actual, "")
    return sorted(drift)
