def merge_payload_ranges(items):
    if not items:
        return []

    for start, end, _ in items:
        if start > end:
            raise ValueError("start > end")

    sorted_items = sorted(items, key=lambda item: (item[0], item[1]))

    result = []
    cur_start, cur_end, cur_payload = sorted_items[0]

    for start, end, payload in sorted_items[1:]:
        if payload == cur_payload and start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            result.append([cur_start, cur_end, cur_payload])
            cur_start, cur_end, cur_payload = start, end, payload

    result.append([cur_start, cur_end, cur_payload])
    return result
